package com.bank.spend.service;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.logging.Logger;

// Finds the K most frequent category ids via frequency map + size-K min-heap.
public class SpendPatternService {
    private static final Logger log = Logger.getLogger(SpendPatternService.class.getName());

    public List<Integer> topKFrequent(int[] categoryIds, int k) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int id : categoryIds) freq.merge(id, 1, Integer::sum); // count occurrences
        // min-heap ordered by frequency: least frequent at the root
        PriorityQueue<Integer> minHeap = new PriorityQueue<>((a, b) -> freq.get(a) - freq.get(b));
        for (int key : freq.keySet()) {
            minHeap.offer(key);
            if (minHeap.size() > k) minHeap.poll();   // drop the least frequent kept
        }
        List<Integer> result = new ArrayList<>(minHeap);
        log.info(() -> "Top " + k + " frequent categories = " + result + " freq=" + freq);
        return result;
    }
}
